use vstd::prelude::*;

verus! {

    // Compute the bitwise XOR of two equal‐length binary strings
    // represented as Vec<char>, where each char is '0' or '1'.
    //
    // For each index i in 0 .. a.len():
    //   if a[i] == b[i] then result[i] = '0' else result[i] = '1'

    fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char>
        requires
            // inputs have the same length
            a.len() == b.len(),
            // each character of a is '0' or '1'
            forall |i: usize| i < a.len() ==> (a.index(i) == '0' || a.index(i) == '1'),
            // each character of b is '0' or '1'
            forall |i: usize| i < b.len() ==> (b.index(i) == '0' || b.index(i) == '1'),
        ensures
            // result has the same length as the inputs
            result.len() == a.len(),
            // for each position, result is '0' iff the inputs agree, '1' otherwise
            forall |i: usize|
                i < a.len() ==>
                    ( result.index(i)
                      ==
                      if a.index(i) == b.index(i) { '0' } else { '1' } )
    {
        let n = a.len();
        let mut res: Vec<char> = Vec::with_capacity(n);
        let mut i: usize = 0;

        // Build the result one character at a time
        while i < n
            invariant
                // bounds on i and res.len
                i <= n,
                res.len() == i,
                // inputs remain the same length n
                a.len() == n,
                b.len() == n,
                // correctness of all positions computed so far
                forall |j: usize|
                    j < i ==>
                        ( res.index(j)
                          ==
                          if a.index(j) == b.index(j) { '0' } else { '1' } ),
            decreases n - i,
        {
            let ai = a.index(i);
            let bi = b.index(i);
            // compute the XOR character
            let xi = if ai == bi { '0' } else { '1' };
            res.push(xi);
            // advance to next position
            i = i + 1;
        }

        res
    }

} // end verus!

